[751] = { en = "The Ravaged Caravan", tier = 1,
  t = "De geplunderde karavaan",
  d = "Je wrikt het deksel open. Binnen zit een volle verzameling erts en mineralen. Dit is nog meer bewijs van de mijnbouw van de Venture Co. in Mulgore. Boven op het erts en de mineralen ligt een stapel papieren, stevig vastgebonden. Je pakt die eruit.$b$bIn de heuvels in het oosten hoor je nauwelijks het geluid van werk. Je ziet rook van een groot vuur.",
  o = "Breng de Venture Co. Documents terug naar Morin Cloudstalker bij Bloodhoof Village.",
  p = "Gegroet, $n. Weet je al iets nieuws over de plannen en het werk van de Venture Co. in ons thuisland?$b$bMisschien willen ze ons land uitbuiten, zoals ze met andere landen deden. Dan maken de Outrunners er snel een einde aan.",
  c = "Het lijkt echt zo: de Venture Co. probeert onze natuurlijke rijkdommen te stelen. Het is goed dat we dit nu zeker weten. En nu lijkt het erop dat we er iets aan moeten doen.",
