},

[398] = { en = "Wanted: Maggot Eye", tier = 1,
  t = "Gezocht: Maggot Eye",
  d = "Gezocht: Maggot Eye!$b$bMaggot Eye is een smerig beest, zelfs voor een gnoll. Hij is ter dood veroordeeld voor zijn misdaden tegen de Forsaken. Deze gemene schurk steelt lijken voor het leger van de Lich King. Maggot Eye is voor het laatst gezien bij Garren's Haunt, ten noorden van Brill. Daar plunderde hij het land.$b$bDe stad Brill biedt een beloning aan de bekwame persoon die het vonnis uitvoert. Laat Executor Zygand de poot van de schurk zien als het werk klaar is.$b$bGenade is voor de zwakken.",
  o = "Dood Maggot Eye en ga met zijn poot terug naar Executor Zygand in Brill voor een beloning.",
  p = "Ja?",
  c = "De gemene daden van Maggot Eye zijn eindelijk gewroken. Misschien sturen jouw dappere daden een duidelijke boodschap naar wie ons volk kwaad wil doen. Namens de stad Brill dank ik je, $N.",
  g = { {"smerig", "foul, filthy"}, {"ter dood veroordeeld", "sentenced to death"}, {"misdaden", "crimes (misdaad)"}, {"schurk", "villain"}, {"lijken", "corpses (lijk)"}, {"plunderde", "pillaged (plunderen)"}, {"bekwame", "capable (bekwaam)"}, {"vonnis", "sentence, verdict"}, {"poot", "paw"}, {"genade", "mercy"}, {"gewroken", "avenged (wreken)"}, {"namens", "on behalf of"} },
},

