[435] = { en = "Escorting Erland", tier = 1,
  t = "Erland begeleiden",
  d = "De wolven buiten gaan niet weg. Ze kijken me kwaadaardig aan, elke keer als ik een stap buiten de deur zet. Ze hebben vast heel veel honger, als ze denken dat ik het eten waard ben.$B$BIk moet me melden bij mijn teamgenoot, de Deathstalker Rane Yorick. En om bij Rane te komen, heb ik hulp nodig tegen die wolven.$B$BBegeleid me alsjeblieft! Er zijn veel wolven daarbuiten. We hebben dus een betere kans als je vrienden hebt die kunnen helpen...",
  o = "Begeleid Erland langs de wolven naar Rane Yorick.",
  c = "Bedankt voor je hulp, $N. Ik was bang dat de gevaren van Silverpine Erland te veel waren geworden. Dankzij jou zie ik dat dat niet zo is.",
  e = "Erland moet Rane Yorick bereiken",
  g = { {"begeleiden", "to escort"}, {"kwaadaardig", "evilly, malicious"}, {"waard", "worth"}, {"melden", "report (zich melden)"}, {"teamgenoot", "teammate"}, {"begeleid", "escort (begeleiden)"}, {"daarbuiten", "out there"}, {"gevaren", "dangers (gevaar)"}, {"dankzij", "thanks to"}, {"bereiken", "to reach"} },
},

[770] = { en = "The Demon Scarred Cloak", tier = 1,
  t = "De mantel met demonenlittekens",
  d = "De gescheurde huid van Ghost Howl heeft nog steeds een vreselijke wond. De wolf kreeg die wond in zijn gevechten tegen de Burning Legion.$B$BMisschien moet iemand in Bloodhoof Village weten dat Ghost Howl dood is....",
  o = "Zoek iemand die Ghost Howl kent.",
  c = "Ik kan mijn oude ogen bijna niet geloven! Heb jij de grote wolf Ghost Howl verslagen? Ik kijk met nieuw respect naar je, jonge $C. Je bent een $C met heel grote vaardigheden!$b$bIk wil je iets geven. Mijn jachtdagen zijn voorbij. Maar het is een eer voor mij als je een van mijn wapens gebruikt als je jaagt.$b$bIk hoop dat het altijd raak is en dat het je roem brengt.$b$bEn laten we hopen dat de geest van Ghost Howl eindelijk rust heeft gevonden.",
  g = { {"mantel", "cloak"}, {"demonenlittekens", "demon scars (demonenlitteken)"}, {"gescheurde", "torn, ragged (scheuren)"}, {"vreselijke", "terrible (vreselijk)"}, {"wond", "wound"}, {"verslagen", "defeated (verslaan)"}, {"vaardigheden", "skills (vaardigheid)"}, {"eer", "honour"}, {"raak", "on target, a hit"}, {"roem", "fame, renown"}, {"geest", "spirit"} },
},

