[452] = { en = "Pyrewood Ambush", tier = 1,
  t = "Hinderlaag in Pyrewood",
  d = "Je bent hier net op tijd, $N!$b$bDe Pyrewood Council kan elk moment terugkomen. Arugal heeft andere dingen te doen in de burcht. Hij gebruikt de Council als marionetten. Zo houdt hij de domme dienaren van Pyrewood onder controle. Maar ik denk dat de zonen van Arugal zich zonder de leiding van de Pyrewood Council tegen hun meester keren.$b$bIk kan ze niet allemaal alleen aan. Ik heb jouw hulp nodig. Samen kunnen we de Council vernietigen voor Lady Sylvanas.",
  o = "Help Deathstalker Faerleia om de Pyrewood Council te doden.",
  c = "Je vocht als een echte volgeling van de Dark Lady, $N. Nu de Council dood is, kunnen we deze stad misschien voor eens en altijd in handen krijgen. En misschien kunnen we Arugal uit Shadowfang Keep verdrijven. Ik groet je!",
  e = "Help Faerleia om de Pyrewood Council te doden",
  g = { {"hinderlaag", "ambush"}, {"burcht", "keep, castle"}, {"marionetten", "puppets (marionet)"}, {"dienaren", "servants, minions (dienaar)"}, {"leiding", "guidance, leadership"}, {"keren", "turn (zich keren tegen)"}, {"kan ze niet aan", "can't handle them (aankunnen)"}, {"vernietigen", "to destroy"}, {"volgeling", "follower, disciple"}, {"voor eens en altijd", "once and for all"}, {"verdrijven", "to drive out"}, {"groet", "salute (groeten)"} },
},

[460] = { en = "Resting in Pieces", tier = 1,
  t = "Rusten in stukken",
  d = "Jij lijkt geen Rot Hide. Goed. Ik had de hoop al opgegeven...$B$BMijn naam is Alaric. Ik was vroeger de eerste dienaar en lijfwacht van Thule. Hij gebruikte zijn magie om me te \"beschermen\" tegen de Plague of Undeath. Maar zijn spreuk gaf me een ondood leven, en daar kan ik niet uit ontsnappen. En nadat hij de vervloekte Rot Hide-gnolls had gemaakt, hakte Thule mijn hoofd eraf... en gaf mijn hoofd aan de gnolls als speelgoed!$B$BBreng me alsjeblieft naar mijn lichaam. Ik denk dat de gnolls het hier in Fenris Keep hebben begraven, bij de stal, in een graf zonder naam.",
  o = "Breng Alaric's Head naar zijn graf.",
  p = "Dit graf is haastig gegraven.",
  c = "Dank je, $N. Ik was bang dat de gnolls mijn lichaam hadden vernietigd. Het is goed om te weten dat ze dat niet deden.",
  g = { {"opgegeven", "given up (opgeven)"}, {"dienaar", "servant"}, {"lijfwacht", "bodyguard"}, {"spreuk", "spell"}, {"ondood", "undead"}, {"ontsnappen", "to escape"}, {"vervloekte", "cursed (vervloekt)"}, {"hakte eraf", "chopped off (afhakken)"}, {"speelgoed", "toy, plaything"}, {"begraven", "buried (begraven)"}, {"stal", "stable"}, {"graf", "grave"}, {"haastig", "hastily"} },
},

[461] = { en = "The Hidden Niche", tier = 1,
  t = "De verborgen nis",
  d = "Ik ken een verborgen nis in de burcht. Daar ligt een voorwerp dat Thule en zijn oude collega's dierbaar is. Er ligt ook iets wat jij misschien nuttig vindt. Breng me erheen!$B$BDe nis is in de zuidwestelijke toren van de burcht, achter een stoffige plank.$B$BNeem mijn lichaam mee, maar laat mijn laarzen hier. Ze pasten me toch nooit...",
  o = "Breng Alaric naar de verborgen nis.",
  p = "Dit is de plek! Breng me dichterbij...",
  c = "Zo, hij is open. Laat me hier. Ik heb de beste dagen van mijn leven in deze burcht doorgebracht. De gedachte dat ik binnen deze muren kan rusten, geeft me troost.$B$BSluit de nis goed af. Ik wil niet dat die Rot Hides me vinden.$B$BO, en neem dit. Je hebt het verdiend.",
  g = { {"nis", "niche, alcove"}, {"voorwerp", "object, item"}, {"dierbaar", "dear, precious"}, {"zuidwestelijke", "southwestern (zuidwestelijk)"}, {"stoffige", "dusty (stoffig)"}, {"plank", "shelf"}, {"laarzen", "boots (laars)"}, {"pasten", "fitted (passen)"}, {"doorgebracht", "spent (doorbrengen)"}, {"gedachte", "thought"}, {"troost", "comfort"}, {"verdiend", "earned (verdienen)"} },
},

[491] = { en = "Wand to Bethor", tier = 1,
  t = "De toverstaf voor Bethor",
  d = "Thule vertelde me eens iets. Lang geleden maakten hij en twee collega's een toverstaf. Ze weefden hem uit de leerlingstaven die elke magiër had. Deze staf was een symbool van hun vriendschap. Thule ging hem later haten, maar hij kon er geen afstand van doen. Hij kon hem ook niet aan de anderen laten. Dus stal hij de staf en verborg hem in Fenris Keep.$B$BHier. Breng de staf naar Bethor Iceshard, een van de vrienden van Thule van vroeger. Ik weet zeker dat hij hem wil hebben.",
  o = "Breng de Woven Wand naar Bethor Iceshard in de Magic Quarter van de Undercity.",
  p = "$N. Heb je Thule Ravenclaw verslagen?",
  c = "...wat is dit? Had Thule onze Woven Wand? Ik dacht dat hij verloren was, toen onze vriendschap brak en hij de kant van de Lich King koos!$B$BHij heeft de kracht ervan zeker niet gebruikt. Als hij dat had gedaan, had ik het gevoeld. En het is goed dat hij hem niet gebruikte...$B$BDit is een geweldige vondst. Ik ben je dankbaar, $N, en je krijgt een beloning.",
  g = { {"toverstaf", "magic wand"}, {"weefden", "wove (weven)"}, {"leerlingstaven", "apprentice wands (leerlingstaf)"}, {"magiër", "mage"}, {"vriendschap", "friendship"}, {"afstand doen van", "to part with"}, {"verborg", "hid (verbergen)"}, {"verslagen", "defeated (verslaan)"}, {"brak", "broke (breken)"}, {"kant", "side"}, {"koos", "chose (kiezen)"}, {"vondst", "find, discovery"}, {"dankbaar", "grateful"} },
},

[972] = { en = "Water Sapta", tier = 1,
  t = "Watersapta",
  c = "Neem de water sapta en zoek de verdorven waterpoel in Silverpine, $N. Ik heb veel vertrouwen in wat je kunt.",
  g = { {"sapta", "sapta: a shaman's ritual offering"}, {"verdorven", "corrupted"}, {"waterpoel", "pool of water"}, {"vertrouwen", "trust, faith"}, {"zoek", "find, look for (zoeken)"} },
},

[2821] = { en = "The Mark of Quality", tier = 4,
  t = "Een keurmerk van kwaliteit",
  d = "Mijn filosofie over leerbewerking is dat het werk van de hoogst mogelijke kwaliteit moet zijn. Geen compromissen. Wie zegt dat kwaliteit er niet toe doet, probeert je grond aan zee in Dun Morogh te verkopen!$B$BIn mijn laatste zoektocht naar materialen van hoge kwaliteit ben ik dikke yetihuiden tegengekomen. De yeti's leven van nature in Feralas, en er zijn er veel in Feral Scar Vale. Ik wil er wat hebben. Voor een stapel van tien geef ik je een van mijn leren producten naar keuze. Als je dat eerlijk vindt, zijn we in zaken.",
  o = "Breng 10 Thick Yeti Hides naar Pratt McGrubben in Feathermoon Stronghold.",
  p = "Voor een stapel van tien dikke yetihuiden krijg je een van mijn gemaakte producten naar keuze. Omdat kwaliteit belangrijk voor me is, kan ik ervoor zorgen dat je een goed product krijgt!$B$BAls je geen yeti's kunt vinden: ik weet waar er misschien een paar zijn. Kijk eens net landinwaarts van de Forgotten Coast, rond Feral Scar Vale.",
  c = "Heb je even stilgestaan bij de structuur van deze huiden? Als ze goed behandeld worden, kunnen deze huiden wel eens sterker zijn dan ijzer. Niet veel mensen weten van deze huiden. Samen met de vele behandelmiddelen die ik ken, kan ik daardoor misschien producten maken met een echt keurmerk van kwaliteit... dankzij jou, natuurlijk!$B$BEn kies nu alsjeblieft uit wat ik je kan aanbieden voor je hulp!",
  g = { {"keurmerk", "mark of quality, hallmark"}, {"leerbewerking", "leatherworking"}, {"hoogst mogelijke", "highest possible"}, {"compromissen", "compromises (compromis)"}, {"er niet toe doet", "doesn't matter (ertoe doen)"}, {"zoektocht", "search, pursuit"}, {"yetihuiden", "yeti hides (yetihuid)"}, {"van nature", "by nature, native"}, {"naar keuze", "of your choice"}, {"in zaken", "in business"}, {"landinwaarts", "inland"}, {"stilgestaan bij", "stopped to consider (stilstaan bij)"}, {"structuur", "texture, structure"}, {"behandeld", "treated (behandelen)"}, {"behandelmiddelen", "treating solutions (behandelmiddel)"} },
},

[4135] = { en = "The Writhing Deep", tier = 4,
  t = "De Writhing Deep",
  d = "In de rugzakken zitten twee dingen. Het eerste is een pakket met goederen dat naar Thalanaar moest. Het tweede is een briefje dat haastig is geschreven aan een onbekende lezer.$B$BHet briefje vertelt over de ontdekking van verraderlijke, insectachtige wezens ten zuiden van de gnollkampen, op een plek die de Writhing Deep heet. De schrijver vond dat hij het zelf moest onderzoeken, alsof het een ernstige bedreiging was voor heel Feralas. Het briefje is ondertekend met \"Raschal of Feathermoon\".$B$BHet lijkt erop dat je hebt gevonden waar Raschal uiteindelijk naartoe is gegaan.",
  o = "Je weet nu waar Raschal voor het laatst is geweest. Zoek verder naar hem of naar zijn overblijfselen in de Writhing Deep. Volgens het briefje ligt die ten zuiden van de Woodpaw-gnollkampen.",
  c = "Je hebt een grote cocon van een vreemde, onbekende aard ontdekt. De cocon voelt slijmerig aan, maar hier en daar steken harde uitsteeksels uit. De cocon is zo hoog en zo breed dat er gemakkelijk een mensachtig wezen in past... en door de vage mensachtige vorm die je door de huid van de cocon ziet, concludeer je dat de cocon inderdaad zo'n wezen omsluit.",
  g = { {"goederen", "goods"}, {"haastig", "hastily"}, {"verraderlijke", "insidious, treacherous (verraderlijk)"}, {"insectachtige", "insect-like, bug-like (insectachtig)"}, {"ernstige", "serious (ernstig)"}, {"bedreiging", "threat"}, {"ondertekend", "signed (ondertekenen)"}, {"overblijfselen", "remains (overblijfsel)"}, {"cocon", "pod, cocoon"}, {"aard", "nature, kind"}, {"slijmerig", "slimy, mucous"}, {"uitsteeksels", "protrusions (uitsteeksel)"}, {"mensachtig", "humanoid"}, {"concludeer", "conclude, surmise (concluderen)"}, {"omsluit", "encloses, encapsulates (omsluiten)"} },
},

[4265] = { en = "Freed from the Hive", tier = 4,
  t = "Bevrijd uit het nest",
  d = "De cocon splijt een beetje open als je hem aanraakt. Je ziet een mannelijke nachtelf die verrassend genoeg nog leeft. Hij lijkt gezond, maar hij is erg verdoofd. Als je hem uit de cocon helpt, begint hij te bewegen.$B$B\"Elune zij dank, je hebt me gered, vriend! Ik... ik ben Raschal. Ik werd verlamd wakker in deze cocon, nadat deze insecten me hadden overmeesterd. Ben je door de Stronghold gestuurd?\"$B$BHet lijkt erop dat je de vermiste koerier hebt gevonden!",
  o = "Bevrijd Raschal uit het nest van de Zukk'ash.$B$BGa terug naar Ginro Hearthkindle in Feathermoon Stronghold en vertel hem dat Raschal leeft en gezond is.",
  p = "Heb je iets te melden, $n?",
  c = "Welkom thuis, $N. Raschal heeft zich net gemeld en me verteld wat er is gebeurd.$B$BIk... nee, de hele Stronghold kan je niet genoeg bedanken voor je grote daad. Zonder jouw hulp op het juiste moment was Raschal dood geweest. En je hielp ons zonder ook maar te fluisteren over een huurlingenloon. Je draagt het teken van een echte held. Weet dat je altijd een vriend hebt in Ginro Hearthkindle.",
  e = "Bevrijd Raschal.",
  g = { {"bevrijd", "freed, free (bevrijden)"}, {"splijt", "splits (splijten)"}, {"verrassend genoeg", "surprisingly"}, {"verdoofd", "stunned, dazed (verdoven)"}, {"zij dank", "thank (Elune zij dank: thank Elune)"}, {"verlamd", "paralysed (verlammen)"}, {"overmeesterd", "overwhelmed, overpowered (overmeesteren)"}, {"vermiste", "missing (vermist)"}, {"koerier", "courier"}, {"melden", "to report"}, {"daad", "deed"}, {"huurlingenloon", "mercenary's fee"}, {"teken", "mark, sign"} },
},

[4266] = { en = "A Hero's Welcome", tier = 4,
  t = "Een heldenontvangst",
  d = "$N, General Shandris Feathermoon wil je persoonlijk spreken. Ze wil je vast bedanken voor je dienst aan de Stronghold. Maar ik weet ook dat ze met je wil praten over de insectachtige wezens die jij en Raschal in het zuiden van Feralas tegenkwamen. De berichten over die Zukk'ash-insecten zijn... op zijn minst angstaanjagend.$B$BGeneral Feathermoon wacht op je in het hoofdgebouw.",
  o = "Spreek met Shandris Feathermoon in Feathermoon Stronghold.",
  c = "$N, ik dank je hartelijk voor de hulp die je ons hebt gegeven. Je moed tegenover een overmacht verdient een beloning die duizend keer groter is. Toch hoop ik dat je dit aanneemt namens de hele Stronghold.$B$BEn nu, als ik mag... wil ik je nog één keer om hulp vragen. Nu we het Zukk'ash-nest hier in Feralas hebben ontdekt, denk ik dat jij de beste keuze bent voor deze missie.",
  g = { {"heldenontvangst", "hero's welcome"}, {"persoonlijk", "personally"}, {"dienst", "service"}, {"tegenkwamen", "came across, faced (tegenkomen)"}, {"op zijn minst", "to say the least"}, {"angstaanjagend", "frightening"}, {"hoofdgebouw", "main building, main compound"}, {"hartelijk", "warmly"}, {"moed", "courage, bravery"}, {"overmacht", "overwhelming odds, superior force"}, {"verdient", "deserves (verdienen)"}, {"namens", "on behalf of"} },
},

[4267] = { en = "Rise of the Silithid", tier = 4,
  t = "De opkomst van de silithid",
  d = "Ik vertrouw je een kopie toe van het verslag dat Raschal maakte over de plaag in het zuidoosten van Feralas. Het hoofdverslag gaat naar Darnassus. Maar ik wil dat jij deze kopie geeft aan een contactpersoon van de Protectorate. Haar naam is Gracina Spiritmight. Ze is een priesteres die in de Temple of the Moon in Darnassus woont. Ze weet veel van dit soort wezens, en het zou ons allemaal helpen als zij dit verslag krijgt.$B$BJe mag gaan. Veel succes, $N. Moge Elune over ons allen waken.",
  o = "Breng Raschal's Report naar Gracina Spiritmight in Darnassus.",
  p = "Welkom in deze heilige tempel, vriend. Het was mij voorspeld dat je hier uit Feathermoon Stronghold zou komen. Heb je het verslag dat Shandris Feathermoon je vroeg te brengen?",
  c = "Wij nachtelfen kennen de verschrikking die in dit verslag staat beschreven. Shandris deed er wijs aan om dit, en jou, naar mij te sturen.$B$BDeze wezens zullen Feralas snel verslinden. Ze zijn werkelijk een van de grootste bedreigingen die we ooit zullen tegenkomen. De insecten die jij en de koerier tegenkwamen, heten de silithid. Ze zijn slechts werktuigen van een van de grootste gevaren waarmee de Horde en de Alliance ooit te maken zullen krijgen.$B$BIk bid dat we de vastberadenheid zullen hebben om ze te verslaan voordat ze ons vernietigen.",
  g = { {"opkomst", "rise"}, {"vertrouw toe", "entrust (toevertrouwen)"}, {"verslag", "report"}, {"plaag", "infestation, plague"}, {"contactpersoon", "contact, associate"}, {"priesteres", "priestess"}, {"moge", "may (mogen)"}, {"waken", "to watch over"}, {"heilige", "holy, blessed (heilig)"}, {"voorspeld", "foretold (voorspellen)"}, {"verschrikking", "terror, horror"}, {"verslinden", "to devour, consume"}, {"werktuigen", "tools (werktuig)"}, {"vastberadenheid", "resolve, determination"} },
},

[2939] = { en = "In Search of Knowledge", tier = 4,
  t = "Op zoek naar kennis",
  d = "De ruïnes van Feralas kunnen behoorlijk gevaarlijk zijn, maar ze kunnen ons veel vertellen over wat hier is gebeurd.$B$BEen paar dagen geleden zocht ik in het puin in het zuiden. Toen ontdekte ik iets wat een gewone staf lijkt. Maar ik krijg het gevoel niet kwijt dat er meer achter zit. Angelas en ik hebben hier onze boeken grondig doorzocht, maar we kunnen er niets over vinden.$B$BIk heb een collega in Darnassus die ons misschien kan vertellen wat dit is, $N. Waarom ga je niet met haar praten om te zien of ze ons kan helpen?",
  o = "Praat met Daryn Lightwind in Rut'theran Village.",
  c = "O, dus Troyas Moonbreeze heeft je gestuurd?$b$b<moppert> ...hij valt me altijd lastig met zijn wilde ideeën dat hij iets belangrijks heeft gevonden...$b$bLuister, $N, ik zal eerlijk zijn. Troyas denkt altijd dat hij iets belangrijks heeft gevonden in die ruïnes. De waarheid is dat alles wat echt waardevol was, waarschijnlijk lang geleden al is opgepot door de ogers of de harpijen die daar nu wonen.$b$bJe mag gerust rondkijken, maar ik weet niet of je hier boeken vindt die je helpen.",
  g = { {"kennis", "knowledge"}, {"ruïnes", "ruins (ruïne)"}, {"behoorlijk", "quite, fairly"}, {"puin", "rubble"}, {"staf", "stave, staff"}, {"kwijt", "rid of (kwijtraken)"}, {"grondig", "thoroughly"}, {"doorzocht", "searched through (doorzoeken)"}, {"moppert", "mutters, grumbles (mopperen)"}, {"valt lastig", "bothers (lastigvallen)"}, {"waardevol", "valuable"}, {"opgepot", "hoarded (oppotten)"}, {"ogers", "ogres (oger)"}, {"harpijen", "harpies (harpij)"}, {"gerust", "freely, by all means"} },
},

[2940] = { en = "Feralas: A History", tier = 4,
  t = "Feralas: A History",
  d = "Het lijkt alsof niemand dit boek in lange tijd heeft geopend. De kaften zijn behoorlijk versleten en de bladzijden zijn geel geworden. Maar als je het bekijkt, merk je dat het misschien precies is wat Troyas zoekt.$B$BJe pakt het op, maar je beseft dat je waarschijnlijk eerst moet vragen of je het mag lenen.",
  o = "Vraag Daryn Lightwind of je haar boek mag lenen.",
  c = "Dus je wilt Feralas: A History lenen?$b$bEven denken...$b$bIk sta je toe om dit boek te lenen, $N, maar alleen als je eerst iets voor mij doet.",
  g = { {"kaften", "covers (kaft)"}, {"behoorlijk", "quite"}, {"versleten", "worn (verslijten)"}, {"bladzijden", "pages (bladzijde)"}, {"merk", "notice (merken)"}, {"beseft", "realise (beseffen)"}, {"lenen", "to borrow"}, {"sta toe", "allow (toestaan)"} },
},

[2969] = { en = "Freedom for All Creatures", tier = 4,
  t = "Vrijheid voor alle wezens",
  d = "De smerige Grimtotem-clan vangt feeëndraken, $N. Jer'kai en ik hebben geen idee wat ze ermee willen doen, maar het is duidelijk dat ze niets goeds van plan zijn.$B$BWe zijn niet sterk genoeg om ons een weg het kamp in te vechten en de gevangen draken te bevrijden, maar misschien met jouw hulp...$B$BAls je wilt, en als je een paar sterke vrienden hebt, laat de wezens dan met deze sleutel uit hun kooi. Zorg ervoor dat ze levend ontsnappen. Ik blijf de hele tijd aan je zijde. Jer'kai blijft hier.",
  o = "Bevrijd met de Bamboo Cage Key de Sprite Darters uit het hok in het Grimtotem-kamp. Minstens 6 Sprite Darters en Kindal Moonweaver moeten het overleven.$B$BJe hebt 6 minuten. Daarna besluit Kindal dat het tijd is om terug te trekken, en dan mislukt de quest.",
  p = "We kunnen niet toestaan dat de Grimtotem-clan deze prachtige wezens vernietigt. Ze moeten uit hun gevangenschap worden bevrijd!",
  c = "Elune zij dank, $N! Je bent een grote zegen voor ons en voor de darters die je hebt gered. Jer'kai en ik hadden de draken nooit zelf kunnen helpen. Jouw ingrijpen in de zaken van de Grimtotem zal niet vergeten worden.$B$BPraat nu met Jer'kai... ik moet me voorbereiden op onze wraak. Ook al zijn de feeëndraken nu vrij, dat betekent niet dat ze vrij blijven. Jer'kai en ik gaan nu in de aanval.",
  e = "Red minstens 6 Sprite Darters van gevangenschap",
  g = { {"smerige", "filthy (smerig)"}, {"feeëndraken", "faerie dragons (feeëndraak)"}, {"niets goeds van plan", "up to no good"}, {"gevangen", "captured (vangen)"}, {"kooi", "cage"}, {"aan je zijde", "by your side"}, {"hok", "pen, enclosure"}, {"terug te trekken", "to retreat (terugtrekken)"}, {"mislukt", "fails (mislukken)"}, {"gevangenschap", "captivity"}, {"zegen", "blessing"}, {"ingrijpen", "intervention"}, {"wraak", "revenge, retribution"}, {"in de aanval", "on the offensive"} },
},

[2970] = { en = "Doling Justice", tier = 4,
  t = "Gerechtigheid uitdelen",
  d = "Zoals ze je al heeft verteld, brengen Kindal en ik de strijd nu naar de Grimtotem. Samen kunnen we nog steeds wat tauren uitschakelen zonder veel gevaar voor onszelf. Maar we zouden graag wat hulp hebben, als je wilt en kunt.$B$BJe hebt het kamp onder ons gezien, maar er zijn er meer in het oosten. Gebruik je eigen tactiek en richt zoveel mogelijk schade aan bij de tauren. We kunnen hier allemaal weer samenkomen als ze de steek van de pijlen van Kindal en van jouw eigen wapens hebben gevoeld.",
  o = "Dood 12 Grimtotem Naturalists, 10 Grimtotem Raiders en 6 Grimtotem Shamans en ga dan terug naar Jer'kai Moonweaver in Feralas.",
  p = "Kindal heeft tijd nodig om zich voor te bereiden, maar we hebben er al tientallen gedood. De Grimtotem-clan weet heel goed dat we in de buurt zijn, en ze zoeken ons op als adders.$B$BZe zullen alles doen wat ze kunnen om onze hoofden van onze lichamen te halen. Je moet alert zijn... nu je je ermee hebt bemoeid, komen ze ook voor jou.",
  c = "Kindal had gelijk over jou, $N. Je hebt er echt aanleg voor. Je bent een ervarener avonturier dan wij allebei, en daarvoor danken we je.$B$BDe Grimtotem-clan is veel vijandiger dan de meeste tauren... ik vraag me af of hun eigen volk hun daden afkeurt. Het zou me niet verbazen. Zoals je waarschijnlijk weet, hebben veel volken op Azeroth banden met minder vriendelijke verwanten.$B$BMaar dat is een gesprek voor een andere dag.",
  g = { {"gerechtigheid", "justice"}, {"uitdelen", "to dole out, hand out"}, {"uitschakelen", "to take out, pick off"}, {"richt schade aan", "deal damage (schade aanrichten)"}, {"steek", "sting"}, {"pijlen", "arrows (pijl)"}, {"tientallen", "dozens"}, {"adders", "vipers (adder)"}, {"bemoeid", "interfered (zich bemoeien)"}, {"aanleg", "knack, talent"}, {"ervarener", "more seasoned, more experienced (ervaren)"}, {"vijandiger", "more hostile (vijandig)"}, {"afkeurt", "disapproves of (afkeuren)"}, {"banden", "ties (band)"}, {"verwanten", "relatives, kin (verwant)"} },
},

[2972] = { en = "Doling Justice", tier = 4,
  t = "Gerechtigheid uitdelen",
  d = "Hier in de wildernis hebben Kindal en ik weinig middelen om je te belonen, maar we willen niet dat je je ondergewaardeerd voelt. Neem mijn zegelring. Als je ooit in de takken van Teldrassil bent, ga dan naar de Temple of the Moon in het hart van Darnassus. Daar vind je mijn High Priestess Tyrande Whisperwind. Aan de ring ziet ze dat het goed met ons gaat, en hij maakt jouw verhaal geloofwaardig.$B$BWe danken je allebei, $N.",
  o = "Breng Jer'kai's Signet Ring naar High Priestess Tyrande Whisperwind in Darnassus.",
  p = "Hallo, kind. Het doet ons plezier dat er meer machtige avonturiers in de tempel zijn. Als je tijd hebt, wil je dan een of twee verhalen vertellen aan de jongere avonturiers? Ik weet dat velen van hen veel aan je wijsheid zouden hebben.$B$BSorry, wat onbeleefd van me. Je bent naar de tempel gekomen om onze hulp te vragen, en ik val je lastig. Vergeef me alsjeblieft. Vertel me wat de dienaren van het Licht voor je kunnen doen.",
  c = "Dat is een geweldig verhaal, $N. Het doet ons plezier dat je niet alleen het drakenvolk hebt geholpen, maar ook een van onze eigen priesteressen. Jer'kai deed er goed aan om je naar mij te sturen. Ik zorg ervoor dat ze haar ring terugkrijgt. Ik heb verkenners die binnenkort richting Feralas gaan. Dit wordt voor hen nog één ding om te onderzoeken tijdens hun missie.$B$BNogmaals bedankt, en voel je hier alsjeblieft thuis.",
  g = { {"wildernis", "wilderness"}, {"middelen", "means (middel)"}, {"ondergewaardeerd", "unappreciated"}, {"zegelring", "signet ring"}, {"takken", "boughs, branches (tak)"}, {"geloofwaardig", "credible"}, {"machtige", "powerful (machtig)"}, {"wijsheid", "wisdom"}, {"onbeleefd", "rude"}, {"val lastig", "impose on, bother (lastigvallen)"}, {"dienaren", "servants (dienaar)"}, {"drakenvolk", "dragonkind"}, {"priesteressen", "priestesses (priesteres)"}, {"verkenners", "scouts (verkenner)"} },
},

[3841] = { en = "An Orphan Looking For a Home", tier = 4,
  t = "Een wees die een thuis zoekt",
  d = "O, hallo, $N. Ik ben zo blij om je weer te zien. Hoe was je reis naar Darnassus?$B$BNou, je zult blij zijn om te horen dat we flink vooruitgang hebben geboekt terwijl je weg was. We hebben zelfs een nest vol eieren gered. Helaas was de moeder al dood voordat we bij haar kwamen.$B$BZeg, wil je er een als huisdier? Het lijkt erop dat ze snel uitkomen, dus ze hebben een goede $Gvader:moeder; nodig. Wat zeg je ervan?$B$BAls je echt interesse hebt, breng dan een van de eieren naar Quentin bij de racebaan in Shimmering Flats. Hij vertelt je meer.",
  o = "Spreek met Quentin in Thousand Needles.",
  p = "Wel hallo, $C.$B$BLaat je niet misleiden door waar ik ben. Ik ben hier echt niet voor de races... hoe vermakelijk ze ook zijn.$B$BIk ben hier in Thousand Needles eigenlijk om alles te onderzoeken wat ik kan, om te ontdekken hoeveel van het land nog te redden is. Het is een soort kruistocht voor me geworden om het gebied nieuw leven in te blazen en aan te vullen met nieuwe, vruchtbare grond. Misschien ontdek ik dat er een waterbron in de buurt is.$B$BZeg me niet dat je niet hebt gemerkt hoe vreemd de overgang tussen Feralas en Thousand Needles is. Er was vreemde magie in het spel toen dat gebeurde.",
  c = "Ah, een ei van een sprite darter, en een dat bijna rijp is, als ik me niet vergis. Bijzonder dat je er een hebt gevonden, en dan ook nog in zo'n goede staat. Ze worden tegenwoordig zelden gezien in Feralas. Ik heb gehoord dat er verschillende stropers in het gebied waren die ze om allerlei redenen probeerden te vangen en te doden. Echt jammer... het zijn zulke prachtige wezens als ze volwassen zijn.$B$BHoe ben je aan zo'n vondst gekomen?",
  g = { {"wees", "orphan"}, {"vooruitgang geboekt", "made progress (vooruitgang boeken)"}, {"helaas", "unfortunately"}, {"uitkomen", "to hatch"}, {"racebaan", "race track"}, {"misleiden", "to fool, mislead"}, {"vermakelijk", "entertaining"}, {"kruistocht", "crusade"}, {"nieuw leven in te blazen", "to revitalize (nieuw leven inblazen)"}, {"vruchtbare", "fertile (vruchtbaar)"}, {"overgang", "transition"}, {"in het spel", "afoot, at play"}, {"rijp", "mature, ripe"}, {"staat", "condition, state"}, {"stropers", "poachers (stroper)"} },
},

[3842] = { en = "A Short Incubation", tier = 4,
  t = "Een korte broedtijd",
  d = "De Moonweavers, hè? Heel interessant. Ik wou dat de sprite darters echt konden begrijpen wat het betekent dat die twee voor ze zorgen. Ze zijn allebei heel bekwaam.$B$BDus ze hebben je het ei als geschenk gegeven. Dan moet jij er verantwoordelijk voor zijn, zo lang als je wilt. Het lijkt erop dat het bijna klaar is om uit te komen, maar we moeten zeker weten dat het gezond is en niet beschadigd.$B$BIk heb maar twee Elixirs of Fortitude nodig voor een kleine spreuk om het ei te beschermen. De rest van de ingrediënten heb ik hier bij me.",
  o = "Breng 2 Elixir of Fortitudes naar Quentin in Thousand Needles.",
  p = "Hoe langer ik hier blijf, hoe meer ik in de verleiding kom om aan deze races mee te doen, $N. Echt verbijsterend...$B$BHeb je de elixers al gevonden? Zodra ik kan zien of het ei gezond wordt of niet, geef ik het aan je terug. Dan bewaar je het tot het klaar is om uit te komen.$B$BLaat het me weten.",
  c = "Geweldig. Deze zijn prima. Geef me even om mijn ingrediënten te mengen, dan zien we hoe goed het met dit ei gaat.",
  g = { {"broedtijd", "incubation"}, {"bekwaam", "capable"}, {"geschenk", "gift"}, {"verantwoordelijk", "responsible"}, {"beschadigd", "damaged (beschadigen)"}, {"spreuk", "spell"}, {"ingrediënten", "components, ingredients (ingrediënt)"}, {"in de verleiding kom", "am tempted (in de verleiding komen)"}, {"verbijsterend", "boggling, baffling"}, {"elixers", "elixirs (elixer)"}, {"zodra", "as soon as"}, {"bewaar", "keep, hold onto (bewaren)"}, {"mengen", "to mix"} },
},

[3843] = { en = "The Newest Member of the Family", tier = 4,
  t = "Het nieuwste lid van de familie",
  d = "Een prachtig exemplaar, $N. Als dit wezen de broedtijd overleeft, wordt het zeker een gezond huisdier!$B$BEr is nog één laatste ding dat ik je zou aanraden, als je dit echt wilt doorzetten. Ga naar Aerie Peak in de Hinterlands. Praat daar met een dwerg die Agnar Beastamer heet. Hij is een meester in het omgaan met dieren en kan je helpen met de laatste stappen van het broeden.$B$BMaar schiet op, $N. Dit ei is breekbaar en houdt het niet lang vol zonder goede zorg.",
  o = "Breng je Fragile Sprite Darter Egg naar de Hinterlands en spreek met Agnar Beastamer. Maar schiet op: je hebt maar 1 uur om hem te vinden, anders sterft het jong in het ei.",
  p = "Gegroet, $N. Hoe kan ik je helpen?",
  c = "Nou, nou, nou... zo eentje heb ik al een drakenleeftijd niet gezien. Een feeëndraak, als ik me niet vergis... en zo te zien van de soort sprite darter. Uitstekend, echt uitstekend.$B$BNou, als dit kleintje gaat uitkomen en sterk en gezond wil worden, moeten we eten voor hem halen. Goed dat je het op tijd bij me hebt gebracht.",
  g = { {"exemplaar", "specimen"}, {"broedtijd", "incubation, gestation"}, {"overleeft", "survives (overleven)"}, {"aanraden", "to suggest, recommend"}, {"doorzetten", "to follow through"}, {"omgaan met", "handling, dealing with"}, {"broeden", "incubation, brooding"}, {"schiet op", "hurry (opschieten)"}, {"breekbaar", "fragile"}, {"houdt vol", "lasts (volhouden)"}, {"jong", "young animal, hatchling"}, {"drakenleeftijd", "dragon's age"}, {"kleintje", "little one"} },
},

})

